1	import { defineHook } from "../lib/hook";
2	import { DOM_IDS, findElement, requireElement } from "../lib/dom_ids";
3	import { PersistedRecord } from "../lib/persisted_record";
4	import { attachScrubber, fractionAt } from "../lib/scrubber";
5	import { scrollFollow } from "../lib/scroll_follow";
6	import { readerSettings } from "../lib/reader_settings_store";
7	import { cycleOption } from "../lib/cycle_option";
8	import { type WordTiming, parseWordTimings, wordSelector } from "../lib/types";
9	import { attachWordMenu } from "./word_menu";
10	
11	interface AudioPlayerDataset {
12	  audioUrl: string;
13	  timingsUrl: string;
14	  initialPosition?: string;
15	  bookTitle?: string;
16	  chapterTitle?: string;
17	  chapterId?: string;
18	  nextChapterId?: string;
19	  nextAudioUrl?: string;
20	  nextTimingsUrl?: string;
21	  nextChapterTitle?: string;
22	  prevChapterId?: string;
23	  prevAudioUrl?: string;
24	  prevTimingsUrl?: string;
25	  prevChapterTitle?: string;
26	}
27	
28	interface PlayerPrefs {
29	  readonly speed: number;
30	  readonly volume: number;
31	  readonly collapsed: boolean;
32	}
33	
34	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
35	  speed: 1,
36	  volume: 1,
37	  collapsed: false,
38	});
39	
40	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
41	
42	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
43	
44	const POSITION_REPORT_INTERVAL_MS = 5000;
45	const SKIP_SECONDS = 10;
46	const AUTO_SCROLL_GRACE_MS = 800;
47	
48	// Play/pause button glyphs. The LV template renders ▶ (as &#9654;) as the
49	// static default; the hook overwrites textContent on every audio play/pause.
50	const PLAY_GLYPH = "▶";
51	const PAUSE_GLYPH = "❚❚";
52	
53	function coercePlayerPrefs(raw: unknown): Partial<PlayerPrefs> {
54	  if (!raw || typeof raw !== "object") return {};
55	  const r = raw as Record<string, unknown>;
56	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
57	  if (typeof r.speed === "number") out.speed = r.speed;
58	  if (typeof r.volume === "number") out.volume = r.volume;
59	  if (typeof r.collapsed === "boolean") out.collapsed = r.collapsed;
60	  return out;
61	}
62	
63	function migrateLegacyPlayerPrefs(): void {
64	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
65	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
66	  const legacyVolume = localStorage.getItem("readaloud-volume");
67	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
68	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
69	    return;
70	  const migrated: PlayerPrefs = {
71	    speed:
72	      legacySpeed !== null
73	        ? Number.parseFloat(legacySpeed)
74	        : PLAYER_PREFS_DEFAULTS.speed,
75	    volume:
76	      legacyVolume !== null
77	        ? Number.parseFloat(legacyVolume)
78	        : PLAYER_PREFS_DEFAULTS.volume,
79	    collapsed: legacyCollapsed === "true",
80	  };
81	  localStorage.setItem(PLAYER_PREFS_KEY, JSON.stringify(migrated));
82	}
83	
84	migrateLegacyPlayerPrefs();
85	const playerPrefs = new PersistedRecord<PlayerPrefs>(
86	  PLAYER_PREFS_KEY,
87	  PLAYER_PREFS_DEFAULTS,
88	  coercePlayerPrefs,
89	);
90	
91	function findActiveWord(
92	  timings: ReadonlyArray<WordTiming>,
93	  ms: number,
94	): number {
95	  let idx = -1;
96	  let lo = 0;
97	  let hi = timings.length - 1;
98	  while (lo <= hi) {
99	    const mid = (lo + hi) >>> 1;
100	    const t = timings[mid];
101	    if (!t) break;
102	    if (ms >= t.startMs && ms < t.endMs) {
103	      idx = mid;
104	      break;
105	    } else if (ms < t.startMs) {
106	      hi = mid - 1;
107	    } else {
108	      idx = mid;
109	      lo = mid + 1;
110	    }
111	  }
112	  if (idx >= 0 && idx < timings.length - 1) {
113	    const next = timings[idx + 1];
114	    if (next && ms >= next.startMs) idx += 1;
115	  }
116	  return idx;
117	}
118	
119	function formatTime(secs: number): string {
120	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
121	  const m = Math.floor(secs / 60);
122	  const s = Math.floor(secs % 60);
123	  return `${m}:${s < 10 ? "0" : ""}${s}`;
124	}
125	
126	// Monotonically increasing player-instance ID. Each hook mount gets one;
127	// shows up in every log line so we can tell apart pre-/post-remount
128	// instances when reading the browser console after the fact.
129	let nextPlayerId = 1;
130	
131	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
132	  (ctx) => {
133	    const audio = requireElement(DOM_IDS.AUDIO_ELEMENT, HTMLAudioElement);
134	    const playPauseBtn = requireElement(DOM_IDS.PLAY_PAUSE_BTN, HTMLElement);
135	    const timeDisplay = findElement(DOM_IDS.TIME_DISPLAY, HTMLElement);
136	    const textContainer = findElement(DOM_IDS.CHAPTER_TEXT, HTMLElement);
137	    const resyncBtn = findElement(DOM_IDS.RESYNC_BTN, HTMLElement);
138	    const speedBadge = findElement(DOM_IDS.SPEED_BADGE, HTMLElement);
139	
140	    if (!audio || !playPauseBtn) return;
141	
142	    const playerId = nextPlayerId++;
143	    // Detailed always-on logging for autoplay debugging. When the user
144	    // reports a symptom ("phone woke up at 11:07 and audio was at 0:00")
145	    // these lines + the chapter/book ids let us line up the JS-side state
146	    // machine with server logs (see reader_live.ex Logger.info calls).
147	    const log = (event: string, extra?: Record<string, unknown>): void => {
148	      const wall = new Date().toISOString();
149	      const t =
150	        typeof performance !== "undefined"
151	          ? Math.round(performance.now())
152	          : Date.now();
153	      const base: Record<string, unknown> = {
154	        player: playerId,
155	        chapter: ctx.dataset.chapterId,
156	        t,
157	      };
158	      if (extra) Object.assign(base, extra);
159	      console.log(`[autoplay ${wall}] ${event}`, base);
160	    };
161	
162	    let timings: ReadonlyArray<WordTiming> = [];
163	    let currentWordIndex = -1;
164	    let lastReportedMs = -1;
165	    let rafId: number | undefined;
166	    let wordMenuCleanup: (() => void) | undefined;
167	    let intersectionObserver: IntersectionObserver | undefined;
168	
169	    const updateTimeDisplay = (): void => {
170	      if (!timeDisplay) return;
171	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
172	    };
173	
174	    const updateSpeedBadge = (speed: number): void => {
175	      if (!speedBadge) return;
176	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
177	    };
178	
179	    const cycleSpeed = (direction: "up" | "down"): void => {
180	      const closest = SPEEDS.reduce((best, s) =>
181	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
182	          ? s
183	          : best,
184	      );
185	      playerPrefs.set({ speed: cycleOption(SPEEDS, closest, direction) });
186	    };
187	
188	    const togglePlayback = (): void => {
189	      if (audio.paused) audio.play();
190	      else audio.pause();
191	    };
192	
193	    const seekToWordIndex = (idx: number): void => {
194	      const t = timings[idx];
195	      if (!t) return;
196	      audio.currentTime = t.startMs / 1000;
197	      if (audio.paused) audio.play();
198	    };
199	
200	    // Word highlighting with auto-scroll
201	    const highlightWord = (ms: number): void => {
202	      if (!textContainer || timings.length === 0) return;
203	      const idx = findActiveWord(timings, ms);
204	      if (idx === currentWordIndex) return;
205	
206	      if (currentWordIndex >= 0) {
207	        const old = textContainer.querySelector<HTMLElement>(
208	          wordSelector(currentWordIndex),
209	        );
210	        old?.classList.remove("word-active");
211	        old?.classList.add("word-spoken");
212	      }
213	
214	      if (idx >= 0) {
215	        const next = textContainer.querySelector<HTMLElement>(
216	          wordSelector(idx),
217	        );
218	        if (next) {
219	          next.classList.add("word-active");
220	          next.classList.remove("word-spoken");
221	
222	          if (!scrollFollow.get().autoScrollPaused) {
223	            scrollFollow.beginAutoScroll(AUTO_SCROLL_GRACE_MS);
224	            next.scrollIntoView({ behavior: "smooth", block: "center" });
225	            if (intersectionObserver) {
226	              intersectionObserver.disconnect();
227	              intersectionObserver.observe(next);
228	            }
229	          }
230	        }
231	      }
232	
233	      if (idx > currentWordIndex) {
234	        for (let i = Math.max(0, currentWordIndex); i < idx; i++) {
235	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
236	          if (el) {
237	            el.classList.remove("word-active");
238	            el.classList.add("word-spoken");
239	          }
240	        }
241	      } else if (idx >= 0 && idx < currentWordIndex) {
242	        for (let i = idx + 1; i <= currentWordIndex; i++) {
243	          const el = textContainer.querySelector<HTMLElement>(wordSelector(i));
244	          if (el) el.classList.remove("word-spoken", "word-active");
245	        }
246	      }
247	
248	      currentWordIndex = idx;
249	    };
250	
251	    const startHighlightLoop = (): void => {
252	      const tick = (): void => {
253	        if (!audio.paused) {
254	          highlightWord(audio.currentTime * 1000);
255	          rafId = requestAnimationFrame(tick);
256	        }
257	      };
258	      rafId = requestAnimationFrame(tick);
259	    };
260	
261	    const stopHighlightLoop = (): void => {
262	      if (rafId !== undefined) {
263	        cancelAnimationFrame(rafId);
264	        rafId = undefined;
265	      }
266	    };
267	
268	    const volSlider = ctx.el.querySelector<HTMLInputElement>(
269	      "[data-volume-slider]",
270	    );
271	
272	    // Player prefs → DOM. Bound to the store so chapter-swap re-renders can't
273	    // desync the slider, the speed badge, or the collapsed class from the
274	    // user's actual preference. The audio element's playbackRate/volume are
275	    // also re-applied here; src changes can reset playbackRate, so the
276	    // loadedmetadata handler below re-runs apply for that case.
277	    const applyPlayerPrefs = (p: Readonly<PlayerPrefs>): void => {
278	      audio.playbackRate = p.speed;
279	      audio.volume = p.volume;
280	      updateSpeedBadge(p.speed);
281	      if (volSlider) volSlider.value = String(p.volume);
282	      ctx.el.classList.toggle("collapsed", p.collapsed);
283	    };
284	    ctx.bindStore(playerPrefs, applyPlayerPrefs);
285	
286	    // The <audio> element has phx-update="ignore" so it's preserved across
287	    // chapter switches (push_patch) AND across LV reconnect/re-mount. The
288	    // hook itself, however, is destroyed and re-mounted on a re-mount —
289	    // so on mount we may find an <audio> element that's already loaded
290	    // (and possibly mid-playback) from a previous hook instance. In that
291	    // case we MUST NOT touch its src — doing so would interrupt the
292	    // user's listening session, which is exactly the bug we're chasing
293	    // with sleeping-mobile autoplay (LV WebSocket times out → re-mount on
294	    // wake → forced reload → 00:00/00:00).
295	    //
296	    // Heuristic: only set src if the element doesn't have one yet (or
297	    // has the page URL, the default for an unset <audio>). If it has
298	    // any other src — network URL, or a `blob:` URL prefetched by a
299	    // previous hook instance — leave it alone.
300	    const wantSrc = ctx.dataset.audioUrl;
301	    const existingSrc = audio.src;
302	    const hasMeaningfulSrc =
303	      existingSrc !== "" &&
304	      existingSrc !== window.location.href &&
305	      existingSrc !== window.location.origin + "/";
306	    log("mount", {
307	      hasMeaningfulSrc,
308	      existingSrcKind: existingSrc.startsWith("blob:")
309	        ? "blob"
310	        : existingSrc === "" || existingSrc === window.location.href
311	          ? "empty"
312	          : "url",
313	      audioPaused: audio.paused,
314	      audioCurrentTime: audio.currentTime,
315	      audioReadyState: audio.readyState,
316	      autoNextChapter: readerSettings.get().autoNextChapter,
317	      hasNext: !!ctx.dataset.nextAudioUrl,
318	      hasPrev: !!ctx.dataset.prevAudioUrl,
319	      bookTitle: ctx.dataset.bookTitle,
320	      chapterTitle: ctx.dataset.chapterTitle,
321	    });
322	    if (!hasMeaningfulSrc) {
323	      log("set-initial-src");
324	      audio.src = wantSrc;
325	      audio.load();
326	    } else {
327	      log("preserve-existing-src");
328	    }
329	
330	    ctx.on(audio, "loadedmetadata", () => {
331	      applyPlayerPrefs(playerPrefs.get());
332	      updateTimeDisplay();
333	      updateMediaSessionPosition();
334	    });
335	    ctx.on(audio, "durationchange", updateTimeDisplay);
336	
337	    // Word timings — fetched on mount and re-fetched whenever we swap to a
338	    // new chapter via swapToChapter().
339	    const fetchTimings = (url: string): void => {
340	      timings = [];
341	      currentWordIndex = -1;
342	      fetch(url)
343	        .then((r) => r.json())
344	        .then((data: unknown) => {
345	          timings = parseWordTimings(data);
346	          if (textContainer && !wordMenuCleanup)
347	            wordMenuCleanup = attachWordMenu(textContainer);
348	        })
349	        .catch((err: unknown) =>
350	          console.error("AudioPlayer: failed to load timings", err),
351	        );
352	    };
353	    fetchTimings(ctx.dataset.timingsUrl);
354	
355	    // Restore initial position — only on a fresh load. On re-mount of an
356	    // already-playing element we'd otherwise rewind the user back to a
357	    // saved position from a different LV session.
358	    const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
359	    if (initialMs > 0 && !hasMeaningfulSrc) {
360	      ctx.on(
361	        audio,
362	        "loadedmetadata",
363	        () => {
364	          audio.currentTime = initialMs / 1000;
365	        },
366	        { once: true },
367	      );
368	    }
369	
370	    // --- Media Session API ----------------------------------------------
371	    // Registers the OS-level lock-screen / notification controls. Without
372	    // this, a sleeping mobile device has no native "next chapter" button
373	    // and the WebSocket-bound LV nav often fails when the device wakes.
374	    // With this, the OS gives us a working next/prev button even when JS
375	    // is throttled, and the audio session keeps the lock screen UI alive
376	    // across chapter swaps (since we reuse the same <audio> element).
377	    const ms =
378	      typeof navigator !== "undefined" && "mediaSession" in navigator
379	        ? navigator.mediaSession
380	        : null;
381	
382	    const updateMediaSessionMetadata = (): void => {
383	      if (!ms) return;
384	      ms.metadata = new MediaMetadata({
385	        title: ctx.dataset.chapterTitle ?? "",
386	        artist: ctx.dataset.bookTitle ?? "",
387	        album: ctx.dataset.bookTitle ?? "",
388	      });
389	    };
390	
391	    const updateMediaSessionPosition = (): void => {
392	      if (!ms || !ms.setPositionState) return;
393	      if (!Number.isFinite(audio.duration) || audio.duration <= 0) return;
394	      try {
395	        ms.setPositionState({
396	          duration: audio.duration,
397	          position: Math.min(audio.currentTime, audio.duration),
398	          playbackRate: audio.playbackRate || 1,
399	        });
400	      } catch {
401	        // Some browsers throw on invalid positions; ignore.
402	      }
403	    };
404	
405	    // --- Next-chapter prefetch -----------------------------------------
406	    // Mobile browsers (iOS Safari especially) suspend network fetches
407	    // when the screen locks. If we wait until `ended` to fetch the next
408	    // chapter's audio, the request stalls and audio.play() never gets a
409	    // valid resource — exactly the bug we're chasing. So while the
410	    // current chapter is still playing (and the device presumably
411	    // awake), download the next chapter's audio fully into a Blob URL.
412	    // On `ended` we swap to the in-memory blob — no network needed.
413	    let currentBlobUrl: string | null = null; // points to in-use audio.src
414	    let prefetchedBlobUrl: string | null = null;
415	    let prefetchedFor: string | null = null;
416	    let prefetchAbort: AbortController | null = null;
417	
418	    const tryStartPrefetch = (): void => {
419	      if (!readerSettings.get().autoNextChapter) return;
420	      const url = ctx.dataset.nextAudioUrl;
421	      if (!url) return;
422	      // Already done or in flight for the same URL? Skip.
423	      if (prefetchedBlobUrl && prefetchedFor === url) return;
424	      if (prefetchAbort && prefetchedFor === url) return;
425	      // Target URL changed (e.g. user manually jumped chapters) — drop
426	      // any in-flight or stale-blob state and restart.
427	      if (prefetchAbort) {
428	        log("prefetch-abort-stale", { for: prefetchedFor });
429	        prefetchAbort.abort();
430	        prefetchAbort = null;
431	      }
432	      if (prefetchedBlobUrl) {
433	        log("prefetch-revoke-stale", { for: prefetchedFor });
434	        URL.revokeObjectURL(prefetchedBlobUrl);
435	        prefetchedBlobUrl = null;
436	      }
437	      prefetchedFor = url;
438	      const abort = new AbortController();
439	      prefetchAbort = abort;
440	      log("prefetch-start", { url });
441	      const startedAt = performance.now();
442	      fetch(url, { signal: abort.signal })
443	        .then((r) => {
444	          if (!r.ok) throw new Error(`HTTP ${r.status}`);
445	          return r.blob();
446	        })
447	        .then((blob) => {
448	          prefetchAbort = null;
449	          if (prefetchedFor !== url) {
450	            log("prefetch-discard-target-changed", {
451	              completedFor: url,
452	              currentTarget: prefetchedFor,
453	            });
454	            return;
455	          }
456	          prefetchedBlobUrl = URL.createObjectURL(blob);
457	          log("prefetch-done", {
458	            url,
459	            bytes: blob.size,
460	            durationMs: Math.round(performance.now() - startedAt),
461	          });
462	        })
463	        .catch((err: unknown) => {
464	          prefetchAbort = null;
465	          if ((err as Error)?.name !== "AbortError") {
466	            log("prefetch-fail", { url, error: String(err) });
467	            console.warn("AudioPlayer: next-chapter prefetch failed", err);
468	            // Reset prefetchedFor so we can retry later (e.g. on next
469	            // timeupdate) instead of being stuck thinking we're done.
470	            if (prefetchedFor === url) prefetchedFor = null;
471	          } else {
472	            log("prefetch-aborted", { url });
473	          }
474	        });
475	    };
476	
477	    // Swap to a different chapter without unmounting the player. Used by
478	    // both the auto-next-on-ended path and (if invoked from outside) by
479	    // server-pushed chapter changes. Critically: same <audio> element, so
480	    // the OS audio session is preserved and lock-screen playback continues
481	    // without requiring a new user gesture.
482	    const swapToChapter = (
483	      audioUrl: string,
484	      timingsUrl: string,
485	      chapterTitle: string,
486	    ): void => {
487	      log("swap-to-chapter", {
488	        srcKind: audioUrl.startsWith("blob:") ? "blob" : "url",
489	        chapterTitle,
490	        audioPaused: audio.paused,
491	      });
492	      audio.src = audioUrl;
493	      audio.load();
494	      // Update title eagerly so the lock screen shows the new chapter name
495	      // even before the LV push_patch round-trip lands.
496	      if (ms) {
497	        ms.metadata = new MediaMetadata({
498	          title: chapterTitle,
499	          artist: ctx.dataset.bookTitle ?? "",
500	          album: ctx.dataset.bookTitle ?? "",
501	        });
502	      }
503	      fetchTimings(timingsUrl);
504	      audio
505	        .play()
506	        .then(() => log("swap-play-ok"))
507	        .catch((err: unknown) => {
508	          log("swap-play-blocked", { error: String(err) });
509	          console.warn("AudioPlayer: chapter-swap play blocked", err);
510	        });
511	    };
512	
513	    const goToNextChapter = (): boolean => {
514	      const networkUrl = ctx.dataset.nextAudioUrl;
515	      const timingsUrl = ctx.dataset.nextTimingsUrl;
516	      const title = ctx.dataset.nextChapterTitle ?? "";
517	      if (!networkUrl || !timingsUrl) {
518	        log("next-chapter-blocked-no-target", {
519	          hasUrl: !!networkUrl,
520	          hasTimings: !!timingsUrl,
521	        });
522	        return false;
523	      }
524	
525	      // Use the prefetched in-memory blob if it's for THIS URL — this is
526	      // the whole point of prefetch and is what makes background-tab
527	      // autoplay actually work. Fall back to the network URL otherwise
528	      // (e.g. desktop user who never triggered prefetch).
529	      const useBlob =
530	        prefetchedBlobUrl !== null && prefetchedFor === networkUrl;
531	      const audioUrl = useBlob ? (prefetchedBlobUrl as string) : networkUrl;
532	      log("go-to-next-chapter", {
533	        useBlob,
534	        prefetchedFor,
535	        prefetchInFlight: prefetchAbort !== null,
536	        toTitle: title,
537	      });
538	
539	      // The blob currently in use as audio.src (if any) is being replaced
540	      // — revoke it so we don't leak ~tens of MB per chapter swap.
541	      if (currentBlobUrl) URL.revokeObjectURL(currentBlobUrl);
542	      currentBlobUrl = useBlob ? audioUrl : null;
543	      // Detach the prefetched-blob slot since it's now the current one
544	      // (or we didn't use it). Either way, the next prefetch (for the
545	      // chapter after this) starts fresh.
546	      prefetchedBlobUrl = null;
547	      prefetchedFor = null;
548	      if (prefetchAbort) {
549	        prefetchAbort.abort();
550	        prefetchAbort = null;
551	      }
552	
553	      swapToChapter(audioUrl, timingsUrl, title);
554	      // Tell the server to push_patch the URL + reload chapter assigns.
555	      // Fire-and-forget: if the WebSocket is asleep (locked phone), the
556	      // event queues until reconnect — audio playback doesn't depend on it.
557	      log("push-event", { event: "next_chapter" });
558	      ctx.pushEvent("next_chapter");
559	      return true;
560	    };
561	
562	    const goToPrevChapter = (): boolean => {
563	      const url = ctx.dataset.prevAudioUrl;
564	      const timingsUrl = ctx.dataset.prevTimingsUrl;
565	      const title = ctx.dataset.prevChapterTitle ?? "";
566	      if (!url || !timingsUrl) {
567	        log("prev-chapter-blocked-no-target");
568	        return false;
569	      }
570	      log("go-to-prev-chapter", { toTitle: title });
571	      swapToChapter(url, timingsUrl, title);
572	      log("push-event", { event: "prev_chapter" });
573	      ctx.pushEvent("prev_chapter");
574	      return true;
575	    };
576	
577	    if (ms) {
578	      updateMediaSessionMetadata();
579	      const safeSet = (
580	        action: MediaSessionAction,
581	        handler: MediaSessionActionHandler | null,
582	      ): void => {
583	        try {
584	          ms.setActionHandler(action, handler);
585	        } catch {
586	          // Browser may not support this action — fine, skip it.
587	        }
588	      };
589	      safeSet("play", () => {
590	        audio.play().catch(() => {});
591	      });
592	      safeSet("pause", () => audio.pause());
593	      safeSet("seekbackward", (details) => {
594	        const delta = details.seekOffset ?? SKIP_SECONDS;
595	        audio.currentTime = Math.max(0, audio.currentTime - delta);
596	      });
597	      safeSet("seekforward", (details) => {
598	        const delta = details.seekOffset ?? SKIP_SECONDS;
599	        const max = Number.isFinite(audio.duration)
600	          ? audio.duration
601	          : Number.POSITIVE_INFINITY;
602	        audio.currentTime = Math.min(max, audio.currentTime + delta);
603	      });
604	      safeSet("seekto", (details) => {
605	        if (typeof details.seekTime === "number") {
606	          audio.currentTime = details.seekTime;
607	        }
608	      });
609	      // Only register next/prev when there's actually a target; otherwise
610	      // the OS UI shows greyed-out buttons (or nothing) which is correct.
611	      if (ctx.dataset.nextAudioUrl) {
612	        safeSet("nexttrack", () => {
613	          log("media-session-nexttrack");
614	          goToNextChapter();
615	        });
616	      } else {
617	        safeSet("nexttrack", null);
618	      }
619	      if (ctx.dataset.prevAudioUrl) {
620	        safeSet("previoustrack", () => {
621	          log("media-session-previoustrack");
622	          goToPrevChapter();
623	        });
624	      } else {
625	        safeSet("previoustrack", null);
626	      }
627	      ctx.onDestroy(() => {
628	        // Clear handlers + metadata so a stale player on a different page
629	        // doesn't get media-key events meant for nothing.
630	        for (const a of [
631	          "play",
632	          "pause",
633	          "nexttrack",
634	          "previoustrack",
635	          "seekbackward",
636	          "seekforward",
637	          "seekto",
638	        ] as MediaSessionAction[]) {
639	          try {
640	            ms.setActionHandler(a, null);
641	          } catch {}
642	        }
643	        ms.metadata = null;
644	      });
645	    }
646	
647	    // Controls
648	    ctx.on(playPauseBtn, "click", togglePlayback);
649	
650	    const skipBack = ctx.el.querySelector<HTMLElement>("[data-skip-back]");
651	    const skipFwd = ctx.el.querySelector<HTMLElement>("[data-skip-forward]");
652	    if (skipBack) {
653	      ctx.on(skipBack, "click", () => {
654	        audio.currentTime = Math.max(0, audio.currentTime - SKIP_SECONDS);
655	      });
656	    }
657	    if (skipFwd) {
658	      ctx.on(skipFwd, "click", () => {
659	        const max = Number.isFinite(audio.duration)
660	          ? audio.duration
661	          : Number.POSITIVE_INFINITY;
662	        audio.currentTime = Math.min(max, audio.currentTime + SKIP_SECONDS);
663	      });
664	    }
665	
666	    const collapseToggle = ctx.el.querySelector<HTMLElement>(
667	      "[data-collapse-toggle]",
668	    );
669	    if (collapseToggle) {
670	      ctx.on(collapseToggle, "click", () => {
671	        playerPrefs.set({ collapsed: !playerPrefs.get().collapsed });
672	      });
673	    }
674	
675	    if (volSlider) {
676	      ctx.on(volSlider, "input", () => {
677	        playerPrefs.set({ volume: Number.parseFloat(volSlider.value) });
678	      });
679	    }
680	
681	    // Scrubbers (main + mini)
682	    const scrubMain = ctx.el.querySelector<HTMLElement>("[data-scrubber]");
683	    const scrubMini = ctx.el.querySelector<HTMLElement>("[data-scrubber-mini]");
684	    const seekToFraction = (f: number): void => {
685	      if (Number.isFinite(audio.duration))
686	        audio.currentTime = f * audio.duration;
687	    };
688	    for (const sc of [scrubMain, scrubMini]) {
689	      if (!sc) continue;
690	      const dispose = attachScrubber<number>({
691	        el: sc,
692	        indexAt: (clientX) => fractionAt(sc, clientX),
693	        preview: () => {},
694	        commit: seekToFraction,
695	      });
696	      ctx.onDestroy(dispose);
697	    }
698	
699	    // Time updates: progress bars + time display + position report.
700	    // Also kicks off the next-chapter prefetch once the user has clearly
701	    // committed to this chapter (>15% through). Doing it here, gated on
702	    // playback progress, means we don't waste bandwidth on chapters the
703	    // user opens and immediately abandons.
704	    const PREFETCH_TRIGGER_FRACTION = 0.15;
705	    ctx.on(audio, "timeupdate", () => {
706	      if (!audio.duration) return;
707	      const pct = (audio.currentTime / audio.duration) * 100;
708	      const fill = ctx.el.querySelector<HTMLElement>("[data-progress-fill]");
709	      if (fill) fill.style.width = `${pct}%`;
710	      const fillMini = ctx.el.querySelector<HTMLElement>(
711	        "[data-progress-fill-mini]",
712	      );
713	      if (fillMini) fillMini.style.width = `${pct}%`;
714	      updateTimeDisplay();
715	
716	      if (audio.currentTime / audio.duration > PREFETCH_TRIGGER_FRACTION) {
717	        tryStartPrefetch();
718	      }
719	
720	      const nowMs = Math.round(audio.currentTime * 1000);
721	      if (
722	        lastReportedMs < 0 ||
723	        Math.abs(nowMs - lastReportedMs) >= POSITION_REPORT_INTERVAL_MS
724	      ) {
725	        lastReportedMs = nowMs;
726	        ctx.pushEvent("audio_position", { position_ms: nowMs });
727	      }
728	    });
729	
730	    // Play/pause icon — bound to the audio element's own state so it stays
731	    // in sync across morphdom patches (chapter swap re-renders #audio-player
732	    // and would otherwise reset the button text to the template default).
733	    ctx.bindElement(audio, ["play", "pause"], () => {
734	      playPauseBtn.textContent = audio.paused ? PLAY_GLYPH : PAUSE_GLYPH;
735	    });
736	
737	    // Side effects on play/pause that aren't DOM projection.
738	    ctx.on(audio, "play", () => {
739	      log("audio-play", {
740	        currentTime: audio.currentTime,
741	        duration: audio.duration,
742	      });
743	      scrollFollow.setPlaying(true);
744	      startHighlightLoop();
745	      if (ms) ms.playbackState = "playing";
746	      updateMediaSessionPosition();
747	    });
748	    ctx.on(audio, "pause", () => {
749	      log("audio-pause", {
750	        currentTime: audio.currentTime,
751	        duration: audio.duration,
752	        atEnd:
753	          Number.isFinite(audio.duration) &&
754	          audio.duration > 0 &&
755	          audio.currentTime >= audio.duration - 0.5,
756	      });
757	      scrollFollow.setPlaying(false);
758	      stopHighlightLoop();
759	      if (ms) ms.playbackState = "paused";
760	      ctx.pushEvent("audio_position", {
761	        position_ms: Math.round(audio.currentTime * 1000),
762	      });
763	    });
764	    ctx.on(audio, "ended", () => {
765	      log("audio-ended", {
766	        autoNext: readerSettings.get().autoNextChapter,
767	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
768	        prefetchInFlight: prefetchAbort !== null,
769	        prefetchedFor,
770	        nextUrl: ctx.dataset.nextAudioUrl ?? null,
771	      });
772	      stopHighlightLoop();
773	      if (readerSettings.get().autoNextChapter) {
774	        // JS-side chapter swap on the same <audio> element. This is the
775	        // critical path for sleeping-mobile autoplay: a full LV navigation
776	        // would tear down the OS audio session and silently fail when the
777	        // device is locked. Same-element src swap keeps the lock-screen
778	        // controls live and the audio session uninterrupted.
779	        goToNextChapter();
780	      }
781	    });
782	    ctx.on(audio, "error", () => {
783	      const err = audio.error;
784	      log("audio-error", {
785	        code: err?.code ?? null,
786	        message: err?.message ?? null,
787	        currentSrc: audio.currentSrc?.startsWith("blob:") ? "blob" : "url",
788	      });
789	    });
790	    ctx.on(audio, "stalled", () =>
791	      log("audio-stalled", { currentTime: audio.currentTime }),
792	    );
793	    ctx.on(audio, "waiting", () =>
794	      log("audio-waiting", { currentTime: audio.currentTime }),
795	    );
796	    ctx.on(audio, "loadedmetadata", () =>
797	      log("audio-loadedmetadata", { duration: audio.duration }),
798	    );
799	
800	    // Re-sync UX
801	    if (resyncBtn) {
802	      ctx.on(resyncBtn, "click", () => {
803	        scrollFollow.resume();
804	        if (currentWordIndex >= 0 && textContainer) {
805	          const el = textContainer.querySelector<HTMLElement>(
806	            wordSelector(currentWordIndex),
807	          );
808	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
809	        }
810	      });
811	    }
812	
813	    if (textContainer && "IntersectionObserver" in window) {
814	      intersectionObserver = new IntersectionObserver(
815	        (entries) => {
816	          for (const entry of entries) {
817	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
818	              scrollFollow.resume();
819	            }
820	          }
821	        },
822	        { threshold: 0.5 },
823	      );
824	      ctx.onDestroy(() => intersectionObserver?.disconnect());
825	    }
826	
827	    ctx.bindStore(scrollFollow, (s) => {
828	      if (!resyncBtn) return;
829	      resyncBtn.classList.toggle("hidden", !s.autoScrollPaused);
830	    });
831	
832	    // Word menu actions
833	    ctx.on(window, "word-action", (detail) => {
834	      if (detail.kind === "play") seekToWordIndex(detail.index);
835	    });
836	
837	    // Speed badge cycle
838	    if (speedBadge) ctx.on(speedBadge, "click", () => cycleSpeed("up"));
839	
840	    // Keyboard-shortcut events
841	    ctx.on(window, "audio:toggle-playback", togglePlayback);
842	    ctx.on(window, "audio:toggle-mute", () => {
843	      audio.muted = !audio.muted;
844	    });
845	    ctx.on(window, "audio:change-speed", ({ direction }) =>
846	      cycleSpeed(direction),
847	    );
848	
849	    // Final cleanup not covered by ctx.on. Important: do NOT pause the
850	    // audio or revoke its current blob URL here. Destroy fires on LV
851	    // reconnect/re-mount (long phone sleep → server LV process times out
852	    // → client re-mount on wake) — and the <audio> element survives
853	    // (phx-update="ignore"). Pausing or revoking would interrupt the
854	    // user's listening session at exactly the moment they wake the phone
855	    // hoping playback continues. If the player is genuinely going away
856	    // (user navigates off the reader), the <audio> element gets removed
857	    // from the DOM, which auto-pauses it — no explicit pause needed.
858	    //
859	    // We do still abort and revoke the *prefetch* slot: that blob is not
860	    // tied to the playing audio element, so leaking it across re-mount
861	    // would just waste memory.
862	    ctx.onDestroy(() => {
863	      log("destroy", {
864	        audioPaused: audio.paused,
865	        currentTime: audio.currentTime,
866	        duration: audio.duration,
867	        prefetchInFlight: prefetchAbort !== null,
868	        hasPrefetchedBlob: prefetchedBlobUrl !== null,
869	      });
870	      stopHighlightLoop();
871	      wordMenuCleanup?.();
872	      if (prefetchAbort) prefetchAbort.abort();
873	      if (prefetchedBlobUrl) URL.revokeObjectURL(prefetchedBlobUrl);
874	    });
875	  },
876	);
