1	// A subscribable readable. Anything matching this shape can be wired into
2	// a hook's DOM via ctx.bindStore. PersistedRecord, scrollFollow, and any
3	// future client-side state container should implement it.
4	//
5	// Lives here (not in lib/hook.ts) so the hook framework and the concrete
6	// stores both depend on it, rather than the stores depending on the hook
7	// framework.
8	export interface ReadableStore<T> {
9	  get(): T;
10	  subscribe(fn: (snapshot: T) => void): () => void;
11	}
12	
13	// Shared listener registry for ReadableStore implementations. Catches
14	// listener exceptions so one bad subscriber can't starve the others —
15	// without this, a throw in a hook's apply function leaves later hooks
16	// permanently desynced from store state.
17	export class Notifier<T> {
18	  private readonly listeners = new Set<(snapshot: T) => void>();
19	
20	  subscribe(fn: (snapshot: T) => void): () => void {
21	    this.listeners.add(fn);
22	    return () => {
23	      this.listeners.delete(fn);
24	    };
25	  }
26	
27	  notify(snapshot: T): void {
28	    for (const fn of this.listeners) {
29	      try {
30	        fn(snapshot);
31	      } catch (err) {
32	        console.error("store listener threw:", err);
33	      }
34	    }
35	  }
36	}
37

