interface WireChapter {
  id: string;
  title?: string | null;
  number: number;
}

export function parseWordTimings(json: unknown): ReadonlyArray<WordTiming> {
  if (!json || typeof json !== "object" || !("timings" in json)) return [];
  const wire =
    (json as { timings?: ReadonlyArray<WireWordTiming> }).timings ?? [];
