  let wire: ReadonlyArray<WireChapter>;
  try {
    wire = JSON.parse(jsonString) as ReadonlyArray<WireChapter>;
  } catch {
    return [];
  }
  return wire.map((c) => ({
    id: ChapterId(c.id),
